import{_ as a,o as s,c as e,a2 as n}from"./chunks/framework.BbQrW5_t.js";const u=JSON.parse('{"title":"走在乡间的小路上","description":"","frontmatter":{"title":"走在乡间的小路上","date":"2026-09-03T00:00:00.000Z","tags":["口琴","基础"]},"headers":[],"relativePath":"study/harmonica/scores/10-走在乡间的小路上.md","filePath":"study/harmonica/scores/10-走在乡间的小路上.md","lastUpdated":1788506840000}'),d={name:"study/harmonica/scores/10-走在乡间的小路上.md"};function l(o,t,i,r,c,p){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="_10-·-走在乡间的小路上-⭐⭐-叶佳修" tabindex="-1">10 · 走在乡间的小路上 ⭐⭐（叶佳修） <a class="header-anchor" href="#_10-·-走在乡间的小路上-⭐⭐-叶佳修" aria-label="Permalink to &quot;10 · 走在乡间的小路上 ⭐⭐（叶佳修）&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>难度</td><td>⭐⭐ 基础</td></tr><tr><td>拍号/速度</td><td>4/4 · ♩= 100（原调 F，本谱 C 调记谱）</td></tr><tr><td>口琴</td><td>C 调（<code>6,</code> 在 10 孔需半压音，初学可用复音琴或改吸 <code>1</code> 过渡）</td></tr><tr><td>目标</td><td>附点节奏、乡村的闲逛感</td></tr></tbody></table><h2 id="简谱-c-调-·-主歌前两句" tabindex="-1">简谱（C 调 · 主歌前两句） <a class="header-anchor" href="#简谱-c-调-·-主歌前两句" aria-label="Permalink to &quot;简谱（C 调 · 主歌前两句）&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>走在乡间的小路上：</span></span>
<span class="line"><span>5  5  5  3  2  1  2 | 3 - - - |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>暮归的老牛是我同伴：</span></span>
<span class="line"><span>3  3  3  2  1  6, 1 | 2 - - - |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>荷把锄头在肩上：</span></span>
<span class="line"><span>2  2  2  1  6, 1  2 | 3 - - - |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>牧童的歌声在荡漾：</span></span>
<span class="line"><span>5  3  5  3  2  1  2 | 1 - - - |</span></span></code></pre></div><h2 id="吹奏要点" tabindex="-1">吹奏要点 <a class="header-anchor" href="#吹奏要点" aria-label="Permalink to &quot;吹奏要点&quot;">​</a></h2><ol><li><code>5 5 5 3 2 1 2</code> 中前三个同音是&quot;走路步点&quot;——均匀，别越吹越快</li><li><code>6,</code> 低音 la 若在 10 孔琴上压音吃力，先用 <code>1</code> 替代不破坏旋律框架，压音单练补课</li><li>全曲保持&quot;散步&quot;的中速，句尾长音 <code>3 - -</code> 像回头看夕阳</li></ol><h2 id="练习任务" tabindex="-1">练习任务 <a class="header-anchor" href="#练习任务" aria-label="Permalink to &quot;练习任务&quot;">​</a></h2><ul><li>[ ] 跟着原曲（蔡琴/校园民歌版）合奏一遍找律动</li><li>[ ] 若用 10 孔琴：把 <code>6,</code> 半压音单练 10 分钟（第 3 孔吸气降半音）</li></ul><h2 id="🗺️-完整演奏地图" tabindex="-1">🗺️ 完整演奏地图 <a class="header-anchor" href="#🗺️-完整演奏地图" aria-label="Permalink to &quot;🗺️ 完整演奏地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>段落</th><th>内容</th><th>本谱覆盖</th></tr></thead><tbody><tr><td>前奏</td><td>4 小节（笛子音色）</td><td>—</td></tr><tr><td>主歌 A（4 句）</td><td>走在乡间…牧童的歌声在荡漾</td><td>✅ 已给 4 句</td></tr><tr><td>尾句 C</td><td>喔呜喔呜喔喔他们唱，还有一支短笛隐约在吹响</td><td>上行旋律，结尾长音落 1</td></tr><tr><td>副歌 B</td><td>整段重复 A 旋律（歌词不同）</td><td>同 A</td></tr></tbody></table><ul><li>和弦参考：<code>C - G - F - C</code> 乡村进行，副歌落 <code>G-C</code></li><li>完整词谱获取：见下方渠道</li></ul><h2 id="📖-完整词谱获取渠道-合法" tabindex="-1">📖 完整词谱获取渠道（合法） <a class="header-anchor" href="#📖-完整词谱获取渠道-合法" aria-label="Permalink to &quot;📖 完整词谱获取渠道（合法）&quot;">​</a></h2><ol><li><strong>曲谱网站</strong>：歌谱简谱网、曲谱自珍网等（个人学习打印常规授权范围）</li><li><strong>音乐 App 曲谱功能</strong>：网易云音乐/QQ 音乐内置歌词+部分曲谱</li><li><strong>正版歌本</strong>：《口琴演奏自学教程》《流行歌曲口琴曲集》等出版物</li><li><strong>最实用</strong>：本页&quot;演奏地图&quot; + 原曲伴奏（各音乐平台均有）——地图定孔位，耳朵定细节</li></ol>`,13)])])}const _=a(d,[["render",l]]);export{u as __pageData,_ as default};
